import math

def interp(points,x):
    p=sorted(points)
    for a,b in zip(p,p[1:]):
        if a[0]<=x<=b[0]:
            f=(x-a[0])/max(1e-6,b[0]-a[0])
            return a[1]+f*(b[1]-a[1])
    return min(p,key=lambda a:abs(a[0]-x))[1]

def control(obs):
    m=obs['local_map']
    left=m['left_rail']; right=m['right_rail']
    look=5.0
    y=(interp(left,look)+interp(right,look))/2
    k=2*y/(look*look+y*y)
    desired=max(-27,min(27,math.degrees(math.atan(3.6*k))))
    h=obs['hitch_deg']
    hr=math.radians(h)
    feed=math.degrees(math.atan2(2.5*math.sin(hr),3.6+1.3*math.cos(hr)))
    steer=max(-43,min(43,feed+1.65*(h-desired)))
    speed=-0.85 if abs(h)<25 else -0.55
    if abs(h)>43:
        wake('Hitch angle needs attention')
        return (0,0,180)
    return (steer,speed,180)

