import math

def control(obs):
    rails=obs.get('local_map',{})
    left=rails.get('left_rail',[])
    right=rails.get('right_rail',[])
    if not left or not right:
        wake('Rail map missing')
        return (0,0,180)
    centres=[((a[0]+b[0])/2,(a[1]+b[1])/2) for a,b in zip(left,right)]
    h=math.radians(obs['hitch_deg'])
    look=9.0
    candidates=[]
    for a,b in zip(centres,centres[1:]):
        if min(a[0],b[0])<=look<=max(a[0],b[0]) and abs(b[0]-a[0])>0.001:
            f=(look-a[0])/(b[0]-a[0])
            candidates.append((look,a[1]+f*(b[1]-a[1])))
    if candidates:
        x,y=min(candidates,key=lambda p:abs(p[1]))
    else:
        ahead=[p for p in centres if p[0]>1]
        if not ahead:
            wake('No course ahead')
            return (0,0,180)
        x,y=min(ahead,key=lambda p:abs(p[0]-look))
    curvature=2*y/max(12,x*x+y*y+3.8*x)
    desired=math.asin(max(-0.73,min(0.73,10.2*curvature)))
    steer=math.degrees(math.atan(3.9*(math.sin(h)/10.55+0.30*(h-desired))))
    steer=max(-42,min(42,steer))
    speed=1.3 if abs(desired)<0.16 and abs(h)<0.22 else 0.85
    if abs(h)>0.85:
        speed=0.5
    if abs(h)>1.02:
        wake('Hitch angle needs recovery')
        return (steer,0,180)
    return (steer,-speed,180)

